function avlHeight(n){ return n?n.h:0; }
function avlBalance(n){ return n?avlHeight(n.left)-avlHeight(n.right):0; }
function avlFix(n){ n.h=1+Math.max(avlHeight(n.left),avlHeight(n.right)); return n; }
function avlRotRight(y){
  var x=y.left, t2=x.right;
  x.right=y; y.left=t2;
  avlFix(y); avlFix(x);
  return x;
}
function avlRotLeft(x){
  var y=x.right, t2=y.left;
  y.left=x; x.right=t2;
  avlFix(x); avlFix(y);
  return y;
}
function avlInsert(root, key, log){
  if(typeof key!=='number'||!isFinite(key)) return { value:root, error:'键必须是有限数' };
  var dup=false;
  function ins(node){
    if(!node) return { key:key, left:null, right:null, h:1 };
    if(key<node.key) node.left=ins(node.left);
    else if(key>node.key) node.right=ins(node.right);
    else { dup=true; return node; }
    avlFix(node);
    var b=avlBalance(node);
    if(b>1 && key<node.left.key){ if(log) log.push('LL@'+node.key+' 右旋'); return avlRotRight(node); }
    if(b<-1 && key>node.right.key){ if(log) log.push('RR@'+node.key+' 左旋'); return avlRotLeft(node); }
    if(b>1 && key>node.left.key){ if(log) log.push('LR@'+node.key+' 先左后右'); node.left=avlRotLeft(node.left); return avlRotRight(node); }
    if(b<-1 && key<node.right.key){ if(log) log.push('RL@'+node.key+' 先右后左'); node.right=avlRotRight(node.right); return avlRotLeft(node); }
    return node;
  }
  var r=ins(root);
  if(dup) return { value:root, error:'重复键 '+key };
  return { value:r, error:null };
}
function avlInorder(root){
  var out=[];
  (function walk(n){ if(!n) return; walk(n.left); out.push(n.key); walk(n.right); })(root);
  return out;
}
function avlValidate(root){
  var okBST=true, okBal=true;
  (function chk(n,lo,hi){
    if(!n) return 0;
    if((lo!==null&&n.key<=lo)||(hi!==null&&n.key>=hi)) okBST=false;
    var hl=chk(n.left,lo,n.key), hr=chk(n.right,n.key,hi);
    if(Math.abs(hl-hr)>1) okBal=false;
    var h=1+Math.max(hl,hr);
    if(n.h!==h) okBal=false;
    return h;
  })(root,null,null);
  return { bst:okBST, balanced:okBal };
}
function avlRender(root){
  if(!root) return '(空树)';
  var lines=[];
  (function draw(n, prefix, isLeft){
    if(!n) return;
    draw(n.right, prefix+(isLeft?'|   ':'    '), false);
    lines.push(prefix+(isLeft?'\\-- ':'/-- ')+n.key+' (h'+n.h+')');
    draw(n.left, prefix+(isLeft?'    ':'|   '), true);
  })(root, '', true);
  return lines.join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { avlInsert:avlInsert, avlInorder:avlInorder, avlValidate:avlValidate,
    avlHeight:avlHeight, avlBalance:avlBalance, avlRender:avlRender };
}
if (typeof window !== 'undefined') {
  window.AvlForgePure = { avlInsert:avlInsert, avlInorder:avlInorder, avlValidate:avlValidate,
    avlHeight:avlHeight, avlBalance:avlBalance, avlRender:avlRender };
}
